  impl_->state_reusable = false;
  auto selection = impl_->runner->SelectNext(
      dynamic_cast<TextRunnerState&>(impl_->lease.state()), impl_->sampler);
  impl_->state_reusable = true;
  if (selection.stop) {
    impl_->stopped = true;
